```suggestion
    let config: unknown
    try {
      config = JSON.parse(fs.readFileSync(configPath, 'utf-8'))
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      throw new Error(`Failed to parse JSON from ${configPath}: ${message}`)
    }
    const threading = (config as any).threading
    if (threading != null) {
      if (typeof threading === 'string') {
